-- Operational modules: check-in, finances, progress, health, notifications and waiting list.
create table if not exists public.gym_checkins(id bigint generated by default as identity primary key,member_id uuid not null references public.members(id) on delete cascade,checked_in_at timestamptz not null default now(),method text not null default 'manual' check(method in('manual','qr')),notes text,created_by uuid references auth.users(id));
create table if not exists public.financial_entries(id bigint generated by default as identity primary key,member_id uuid references public.members(id) on delete set null,kind text not null check(kind in('income','expense')),category text not null,amount numeric(10,2) not null check(amount>=0),occurred_on date not null default current_date,notes text,created_by uuid references auth.users(id),created_at timestamptz not null default now());
create table if not exists public.member_measurements(id bigint generated by default as identity primary key,member_id uuid not null references public.members(id) on delete cascade,measured_on date not null default current_date,weight_kg numeric(5,2),body_fat_percent numeric(5,2),waist_cm numeric(5,2),notes text,created_by uuid references auth.users(id),created_at timestamptz not null default now());
create table if not exists public.member_health_profiles(member_id uuid primary key references public.members(id) on delete cascade,emergency_contact text,conditions text,injuries text,medications text,ems_consent boolean not null default false,consent_at timestamptz,notes text,updated_by uuid references auth.users(id),updated_at timestamptz not null default now());
create table if not exists public.outbound_notifications(id bigint generated by default as identity primary key,member_id uuid references public.members(id) on delete cascade,channel text not null check(channel in('email','sms','push')),title text not null,body text not null,status text not null default 'draft' check(status in('draft','queued','sent','failed')),scheduled_at timestamptz,created_by uuid references auth.users(id),created_at timestamptz not null default now());
create table if not exists public.basement_waiting_list(id bigint generated by default as identity primary key,slot_id bigint not null references public.basement_slots(id) on delete cascade,member_id uuid not null references auth.users(id) on delete cascade,status text not null default 'waiting' check(status in('waiting','promoted','cancelled')),created_at timestamptz not null default now(),unique(slot_id,member_id,status));
alter table public.basement_bookings add column if not exists checked_in_at timestamptz,add column if not exists completed_at timestamptz,add column if not exists notes text,add column if not exists payment_status text not null default 'unpaid';
alter table public.basement_bookings drop constraint if exists basement_bookings_status_check;
alter table public.basement_bookings add constraint basement_bookings_status_check check(status in('booked','cancelled','completed','no_show'));
alter table public.basement_bookings drop constraint if exists basement_bookings_payment_status_check;
alter table public.basement_bookings add constraint basement_bookings_payment_status_check check(payment_status in('unpaid','paid'));
alter table public.gym_checkins enable row level security;alter table public.financial_entries enable row level security;alter table public.member_measurements enable row level security;alter table public.member_health_profiles enable row level security;alter table public.outbound_notifications enable row level security;alter table public.basement_waiting_list enable row level security;
drop policy if exists staff_manage_checkins on public.gym_checkins;drop policy if exists member_read_checkins on public.gym_checkins;drop policy if exists staff_manage_finances on public.financial_entries;drop policy if exists staff_manage_measurements on public.member_measurements;drop policy if exists member_read_measurements on public.member_measurements;drop policy if exists staff_manage_health on public.member_health_profiles;drop policy if exists member_read_health on public.member_health_profiles;drop policy if exists staff_manage_notifications on public.outbound_notifications;drop policy if exists member_read_notifications on public.outbound_notifications;drop policy if exists staff_manage_waitlist on public.basement_waiting_list;drop policy if exists member_manage_own_waitlist on public.basement_waiting_list;
create policy staff_manage_checkins on public.gym_checkins for all to authenticated using(public.is_staff()) with check(public.is_staff());
create policy member_read_checkins on public.gym_checkins for select to authenticated using(exists(select 1 from public.members m where m.id=member_id and m.auth_user_id=(select auth.uid())));
create policy staff_manage_finances on public.financial_entries for all to authenticated using(public.is_staff()) with check(public.is_staff());
create policy staff_manage_measurements on public.member_measurements for all to authenticated using(public.is_staff()) with check(public.is_staff());
create policy member_read_measurements on public.member_measurements for select to authenticated using(exists(select 1 from public.members m where m.id=member_id and m.auth_user_id=(select auth.uid())));
create policy staff_manage_health on public.member_health_profiles for all to authenticated using(public.is_staff()) with check(public.is_staff());
create policy member_read_health on public.member_health_profiles for select to authenticated using(exists(select 1 from public.members m where m.id=member_id and m.auth_user_id=(select auth.uid())));
create policy staff_manage_notifications on public.outbound_notifications for all to authenticated using(public.is_staff()) with check(public.is_staff());
create policy member_read_notifications on public.outbound_notifications for select to authenticated using(exists(select 1 from public.members m where m.id=member_id and m.auth_user_id=(select auth.uid())));
create policy staff_manage_waitlist on public.basement_waiting_list for all to authenticated using(public.is_staff()) with check(public.is_staff());
create policy member_manage_own_waitlist on public.basement_waiting_list for all to authenticated using(member_id=(select auth.uid())) with check(member_id=(select auth.uid()));
grant select,insert,update,delete on public.gym_checkins,public.financial_entries,public.member_measurements,public.member_health_profiles,public.outbound_notifications,public.basement_waiting_list to authenticated;
